const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '速度单位换算' },
      { kind: 'text', payload: '换算项目' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '换算结果' },
      { kind: 'text', payload: '54 km/h → m/s' },
      { kind: 'text', payload: '54 ÷ 3.6' },
      { kind: 'text', payload: '15.0 m/s' },
      { kind: 'text', payload: '换算依据：1 m/s = 3.6 km/h，故 km/h 数值除以 3.6；结果保留三位有效数字。' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.min(w * 0.07, 56);
    var tableX = margin;
    var tableW = w - margin * 2;
    var titleY = h * 0.10;
    var headerTop = h * 0.20;
    var headerH = Math.min(h * 0.14, 60);
    var rowH = Math.min(h * 0.16, 72);
    var bottom = headerTop + headerH + rowH;
    var col1 = tableX + tableW * 0.34;
    var col2 = tableX + tableW * 0.67;
    var center1 = tableX + (col1 - tableX) / 2;
    var center2 = col1 + (col2 - col1) / 2;
    var center3 = col2 + (tableX + tableW - col2) / 2;
    var headerCenterY = headerTop + headerH / 2;
    var rowCenterY = headerTop + headerH + rowH / 2;
    var tableBg = [['M', tableX, headerTop], ['L', tableX + tableW, headerTop], ['L', tableX + tableW, headerTop + headerH], ['L', tableX, headerTop + headerH], ['Z']];
    var topLine = [['M', tableX, headerTop], ['L', tableX + tableW, headerTop]];
    var hlineHeader = [['M', tableX, headerTop + headerH], ['L', tableX + tableW, headerTop + headerH]];
    var bottomLine = [['M', tableX, bottom], ['L', tableX + tableW, bottom]];
    var leftLine = [['M', tableX, headerTop], ['L', tableX, bottom]];
    var rightLine = [['M', tableX + tableW, headerTop], ['L', tableX + tableW, bottom]];
    var vline1 = [['M', col1, headerTop], ['L', col1, bottom]];
    var vline2 = [['M', col2, headerTop], ['L', col2, bottom]];
    var paths = [
      { id: 'tableBg', commands: tableBg },
      { id: 'topLine', commands: topLine },
      { id: 'hlineHeader', commands: hlineHeader },
      { id: 'bottomLine', commands: bottomLine },
      { id: 'leftLine', commands: leftLine },
      { id: 'rightLine', commands: rightLine },
      { id: 'vline1', commands: vline1 },
      { id: 'vline2', commands: vline2 }
    ];
    var children = [
      { type: 'path', pathId: 'tableBg', fill: '#EAF0F8' },
      { type: 'path', pathId: 'topLine', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'hlineHeader', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'bottomLine', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'leftLine', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'rightLine', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'vline1', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'vline2', fill: '#26354A', stroke: { width: 2 } },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: w / 2, y: titleY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: center1, y: headerCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: center2, y: headerCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[3].contentId, anchor: { x: center3, y: headerCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[4].contentId, anchor: { x: center1, y: rowCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[5].contentId, anchor: { x: center2, y: rowCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[6].contentId, anchor: { x: center3, y: rowCenterY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' },
      { type: 'label', contentId: metrics[7].contentId, anchor: { x: w / 2, y: bottom + Math.min(h * 0.11, 52) }, hAlign: 'center', vAlign: 'middle', color: '#44546A' }
    ];
    return { schemaVersion: 1, sceneId: 'unit-conversion-table', revision: input.revision, viewBox: { x: 0, y: 0, width: w, height: h }, paths: paths, root: { type: 'group', children: children } };
  }
};
